"""Evaluate how well CVAE-generated masks work when trained on the MA task.

For every kernel k in 3..10 the same MasckedMLP is trained (5000 steps,
Adam, batch 128) with masks taken from several sources:
  * random      : i.i.d. Bernoulli(p=0.2) masks                    (baseline)
  * ideal       : support confined to the last k rows (the theoretically
                  optimal support for y = MA(k)); sparsity = k*16/512
  * cvae        : masks generated by the trained CVAE (conditioned on the
                  nearest trained kernel 3/5/7/9 for held-out k)
  * mean_imp    : top-K of the average training importance map (baseline)
  * det_reg     : top-K of a deterministic MLP regressor (k,s) -> imp map
  * top10%      : actual selected best-10% masks (only for k in 3,5,7,9;
                  reference ceiling of the selection stage)

Reported metric: per-MLP validation MSE after training (mean / median / min
over the batch of MLPs) on a fixed 10k validation set per kernel.

For every (k, s) all methods are trained together in ONE batched round
(5 x 128 MLPs concatenated), then val_loss is split back per method.

Usage:
    python evaluation/eval_generated_masks.py [--steps 5000] [--n_masks 128]
"""

import argparse
import json
import sys
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import torch

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

import config  # noqa: E402
from data.generate import make_dataset  # noqa: E402
from evaluation.baselines import DetRegressor, MeanImportance  # noqa: E402
from models.cvae import CVAE  # noqa: E402
from models.mlp import (  # noqa: E402
    BatchedMaskedMLP, generate_masks, get_train_batch,
)

EVAL_KERNELS = [3, 4, 5, 6, 7, 8, 9, 10]
TRAINED_KERNELS = config.KERNELS
TRAINED_OFFSETS = config.OFFSETS
OUT_DIR = config.OUTPUTS / "eval"
BASE_METHODS = ["random", "ideal", "cvae", "mean_imp", "det_reg"]


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(description="Evaluate generated masks on MA.")
    p.add_argument("--steps", type=int, default=5000)
    p.add_argument("--n_masks", type=int, default=128,
                   help="MLPs trained per (kernel, method)")
    p.add_argument("--batch_size", type=int, default=config.TRAIN_BATCH_SIZE)
    p.add_argument("--lr", type=float, default=config.LR)
    p.add_argument("--gpu_id", type=int, default=None,
                   help="split kernels across GPUs (0-indexed)")
    p.add_argument("--num_gpus", type=int, default=1,
                   help="total number of GPUs")
    p.add_argument("--offsets", type=int, nargs="+", default=None,
                   help="offsets to evaluate (default: [0])")
    p.add_argument("--eval_pairs", type=str, default=None,
                   help="space-separated 'k,s' pairs, e.g. '3,0 3,2 5,0 5,2'")
    return p


def masks_for_method(k: int, s: int, method: str, n: int, model,
                     device, mean_imp=None, det_reg=None) -> torch.Tensor:
    """Return an (n, L, H) float0/1 mask batch for the given method."""
    k_active = round(config.P * config.L * config.H)
    if method == "random":
        return generate_masks(n, config.L, config.H, config.P,
                              seed=k * 1000 + 1).to(device)
    if method == "ideal":
        m = torch.zeros(n, config.L, config.H)
        m[:, config.L - s - k: config.L - s] = 1.0
        return m.to(device)
    if method == "cvae":
        lab_k = torch.tensor([float(k)], device=device)
        lab_s = torch.tensor([float(s)], device=device)
        s_mask = model.sample_det(lab_k, lab_s, k_active)
        return s_mask.reshape(1, config.L, config.H).expand(n, -1, -1).to(device)
    if method == "mean_imp":
        base = mean_imp(k, s, k_active)
        return base.unsqueeze(0).expand(n, -1, -1).to(device)
    if method == "det_reg":
        base = det_reg.mask(k, s, k_active)
        return base.unsqueeze(0).expand(n, -1, -1).to(device)
    raise ValueError(method)


def train_and_eval(masks: torch.Tensor, kernel: int, offset: int, steps: int,
                   batch_size: int, lr: float, x_val, y_val) -> torch.Tensor:
    """Train n MLPs on the given masks; return per-MLP val MSE (n,)."""
    n = masks.size(0)
    model = BatchedMaskedMLP(n, config.L, config.H).to(x_val.device)
    model.load_masks(masks)
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    seed0 = kernel * 10_003 + offset * 10_007 + n
    for step in range(steps):
        xb, yb = get_train_batch(kernel, offset, batch_size, config.L,
                                 seed0 + step)
        xb, yb = xb.to(x_val.device), yb.to(x_val.device)
        pred = model(xb)
        loss = torch.nn.functional.mse_loss(
            pred, yb.unsqueeze(1).expand_as(pred))
        opt.zero_grad(set_to_none=True)
        loss.backward()
        opt.step()
    return model.val_loss(x_val, y_val, config.VAL_BATCH_SIZE)


def main() -> None:
    args = build_parser().parse_args()
    OUT_DIR.mkdir(parents=True, exist_ok=True)

    if args.eval_pairs is not None:
        grid = []
        for token in args.eval_pairs.split():
            k, s = token.split(",")
            grid.append((int(k), int(s)))
    else:
        offsets = args.offsets if args.offsets is not None else [0]
        grid = [(k, s) for k in EVAL_KERNELS for s in offsets]

    suffix = ""
    if args.gpu_id is not None:
        grid = [pair for i, pair in enumerate(grid)
                if i % args.num_gpus == args.gpu_id]
        suffix = f"_gpu{args.gpu_id}"
        print(f"[eval] gpu {args.gpu_id}/{args.num_gpus} -> (k, s) {grid}",
              flush=True)

    device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
    cvae = CVAE(config.MASK_DIM, config.LATENT_DIM, config.CVAE_HIDDEN)
    cvae.load_state_dict(torch.load(config.CVAE_DIR / "cvae_best.pt",
                                    weights_only=True))
    cvae.to(device).eval()

    mean_imp = MeanImportance()
    det_reg = None
    if "det_reg" in BASE_METHODS:
        det_reg = DetRegressor()
        det_reg.load_state_dict(torch.load(OUT_DIR / "det_reg.pt",
                                           weights_only=True))
        det_reg.eval()

    results = {}          # (kernel, offset, method) -> dict of stats
    for k, s in grid:
        val = make_dataset(k, s, config.N_VAL_SAMPLES, seed=1000 + k + s * 100)
        x_val, y_val = val["x"].to(device), val["y"].to(device)

        methods = list(BASE_METHODS)
        if k in TRAINED_KERNELS and s in TRAINED_OFFSETS:
            methods.append("top10%")

        methods_and_masks = []
        for method in methods:
            if method == "top10%":
                d = torch.load(config.kernel_dir(k, s) / "best10pct.pt",
                               weights_only=True)
                masks = d["masks"][:args.n_masks].to(device)
            else:
                masks = masks_for_method(k, s, method, args.n_masks, cvae,
                                         device, mean_imp, det_reg)
            methods_and_masks.append((method, masks))

        # Train every method's MLPs in one batched round, then split val loss.
        all_masks = torch.cat([m for _, m in methods_and_masks], dim=0)
        all_vl = train_and_eval(all_masks, k, s, args.steps, args.batch_size,
                                args.lr, x_val, y_val)

        idx = 0
        for method, masks in methods_and_masks:
            n = masks.size(0)
            vl = all_vl[idx:idx + n]
            idx += n
            stats = {"mean": vl.mean().item(), "median": vl.median().item(),
                     "min": vl.min().item(),
                     "sparsity_masks": masks.mean().item()}
            results[(k, s, method)] = stats
            print(f"[eval] k={k} s={s} {method:6s}: "
                  f"mean={stats['mean']:.3e} med={stats['median']:.3e} "
                  f"min={stats['min']:.3e} sp={stats['sparsity_masks']:.3f}",
                  flush=True)

    out_pt = OUT_DIR / f"eval_results{suffix}.pt"
    out_json = OUT_DIR / f"eval_results{suffix}.json"
    torch.save(results, out_pt)
    with open(out_json, "w") as f:
        json.dump({f"{k}:{s}:{m}": st for (k, s, m), st in results.items()},
                  f, indent=2)
    print(f"[eval] saved -> {out_json}")

    if args.gpu_id is None:
        if args.eval_pairs is not None:
            eval_offsets = sorted(set(s for _, s in grid))
        else:
            eval_offsets = offsets
        plot_results(results, eval_offsets)


def plot_results(results: dict, offsets: list) -> None:
    order = ["random", "mean_imp", "det_reg", "cvae", "top10%", "ideal"]
    config.PLOT_EVAL_DIR.mkdir(parents=True, exist_ok=True)
    n_methods = len(order)
    width = 0.9 / (n_methods + 1)
    fig, axes = plt.subplots(1, len(offsets), figsize=(6 * len(offsets), 5),
                             squeeze=False)
    x = np.arange(len(EVAL_KERNELS))
    for ax, s in zip(axes.flat, offsets):
        for i, m in enumerate(order):
            means = [results.get((k, s, m), {"mean": np.nan})["mean"]
                     for k in EVAL_KERNELS]
            ax.bar(x + (i - (n_methods - 1) / 2) * width, means, width,
                   label=m)
        ax.set_xticks(x)
        ax.set_xticklabels([f"k={k}" for k in EVAL_KERNELS])
        ax.set_yscale("log")
        ax.set_xlabel("kernel")
        ax.set_ylabel("mean val MSE after 5000 steps (log)")
        ax.set_title(f"offset s={s}")
        ax.legend()
        ax.grid(alpha=0.3, which="both")
    fig.suptitle("Generated vs ideal vs random masks on the MA(k, s) task")
    fig.tight_layout()
    out = config.PLOT_EVAL_DIR / "eval_mse.png"
    fig.savefig(out, dpi=130)
    plt.close(fig)
    print(f"[eval] plot -> {out}")


if __name__ == "__main__":
    main()